return [{ json: {
  competitor_url: 'https://example.com',
  your_angle: 'privacy-first, no account required',
  authorized: true
} }];

const j = $input.first().json;
const e = [];
try { const u = new URL(j.competitor_url); if (!/^https?:$/.test(u.protocol)) e.push('competitor_url must be http(s)'); } catch { e.push('competitor_url must be a valid URL'); }
if (j.authorized !== true) e.push('authorized must be true: only analyze pages you are permitted to access');
if (e.length) throw new Error('Blocked: ' + e.join('; '));
return [{ json: j }];

const src = $input.first().json;
const html = (src.data || src.body || '').toString();
if (!html) throw new Error('Empty page body; cannot analyze (site may block fetching)');
const pick = (re) => { const m = html.match(re); return m ? m[1].replace(/\s+/g, ' ').trim().slice(0, 200) : ''; };
const title = pick(/<title[^>]*>([^<]*)<\/title>/i);
const desc = pick(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i);
const h1s = [...html.matchAll(/<h1[^>]*>([\s\S]*?)<\/h1>/gi)].map(m => m[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim()).filter(Boolean).slice(0, 5);
const ctas = [...html.matchAll(/<(?:button|a)[^>]*>([\s\S]*?)<\/(?:button|a)>/gi)].map(m => m[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim()).filter(t => /sign up|start|try|buy|get|free|demo/i.test(t)).slice(0, 8);
const j = $('Validate Input').first().json;
return [{ json: {
  competitor_url: j.competitor_url,
  observed: { title, meta_description: desc, headlines: h1s, cta_samples: [...new Set(ctas)] },
  your_angle: j.your_angle || '',
  differentiation_brief: [
    'How the competitor positions itself: ' + (title || '(no title)'),
    'Their primary CTAs suggest the conversion path above.',
    'Your stated angle to differentiate: ' + (j.your_angle || '(define one)'),
    'Ethical next step (MANUAL): build your OWN original product around your angle; write honest comparison content, not scraped clones or spam pages.'
  ],
  note: 'Research only. No site was cloned; no bulk SEO pages generated.'
} }];
